with valid as (select *, case when budget >= 4305000 then 'High' when budget >= 1931000 then 'Medium' else 'Low' end as budget_band, substring(location, 1, 2) as location_prefix, coalesce(dept_name, 'DIRECT') as dept_name_clean from departments where location = 'Chiang Mai') select id, location_prefix, dept_name_clean, ntile(4) over (partition by dept_name order by budget desc, id) as budget_bucket, sum(budget) over (partition by location order by budget, id rows between unbounded preceding and current row) as cumulative_budget from valid
